/**
 * ds-lint: the standard's code rules for an app. UI code uses semantic tokens and DSIcon only:
 * no colour literals, no stock palette classes, no platform or third-party icon sets, no inline
 * SVG. Generated files (header "GENERATED by ...") and the design/ folder are skipped.
 */
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { join, relative } from "node:path";

export type Rule = "hex-color" | "stock-palette" | "icon-library" | "platform-icons" | "inline-svg";
export interface Finding {
  file: string;
  line: number;
  rule: Rule;
  match: string;
}
export interface LintConfig {
  rules?: Partial<Record<Rule, "off" | "error">>;
  allowPalettes?: string[];
  ignore?: string[];
}

const SKIP_DIRS = new Set(["node_modules", ".git", "build", "dist", ".next", "out", "Pods", "DerivedData", "generated", ".turbo", ".gradle"]);
const CODE = /\.(tsx?|jsx?|css|html|swift|kt|dart)$/;
const MARKUP = /\.(tsx|jsx|html)$/;
const WEB = /\.(tsx?|jsx?|css|html)$/;
const STOCK =
  /\b(?:[a-z-]+:)*(?:bg|text|border|ring|fill|stroke|from|to|via|outline|decoration|divide|placeholder|shadow|accent|caret)-(slate|gray|zinc|neutral|stone|red|orange|amber|yellow|lime|green|emerald|teal|cyan|sky|blue|indigo|violet|purple|fuchsia|pink|rose)-(?:50|[1-9]00|950)\b/g;
const ICON_LIBS = /from\s+['"](lucide-react(?:-native)?|react-icons[^'"]*|@heroicons\/[^'"]+|@phosphor-icons\/[^'"]+|@tabler\/icons[^'"]*|@expo\/vector-icons[^'"]*|react-native-vector-icons[^'"]*|@mui\/icons-material[^'"]*|react-feather|ionicons[^'"]*)['"]/g;

interface Matcher {
  rule: Rule;
  applies: (file: string) => boolean;
  find: (line: string) => string[];
}

const all = (re: RegExp, group = 0) => (line: string) => [...line.matchAll(re)].map((m) => m[group]);

const MATCHERS: Matcher[] = [
  { rule: "hex-color", applies: (f) => /\.css$/.test(f), find: all(/#[0-9a-fA-F]{3,8}\b/g) },
  { rule: "hex-color", applies: (f) => CODE.test(f) && !/\.css$/.test(f), find: all(/["'`](#[0-9a-fA-F]{3,8})["'`]/g, 1) },
  { rule: "hex-color", applies: (f) => /\.(kt|dart)$/.test(f), find: all(/Color\((0x[0-9A-Fa-f]{6,8})\)/g, 1) },
  { rule: "stock-palette", applies: (f) => WEB.test(f), find: all(STOCK) },
  { rule: "icon-library", applies: (f) => WEB.test(f), find: all(ICON_LIBS, 1) },
  { rule: "platform-icons", applies: (f) => f.endsWith(".swift"), find: all(/\bsystem(?:Name|Image)\s*:\s*"[^"]*"/g) },
  {
    rule: "platform-icons",
    applies: (f) => f.endsWith(".kt"),
    find: all(/androidx\.compose\.material\.icons[\w.]*|\bIcons\.(?:Default|Filled|Outlined|Rounded|Sharp|TwoTone|AutoMirrored)\b[\w.]*/g),
  },
  { rule: "platform-icons", applies: (f) => f.endsWith(".dart"), find: all(/\b(?:Cupertino)?Icons\.\w+/g) },
  { rule: "inline-svg", applies: (f) => MARKUP.test(f), find: all(/<svg\b/g) },
];

function walk(root: string, dir: string, ignore: string[]): string[] {
  const out: string[] = [];
  for (const name of readdirSync(dir)) {
    const full = join(dir, name);
    const rel = relative(root, full);
    if (ignore.some((p) => rel === p || rel.startsWith(`${p}/`))) continue;
    if (statSync(full).isDirectory()) {
      if (!SKIP_DIRS.has(name) && !name.startsWith(".") && rel !== "design") out.push(...walk(root, full, ignore));
    } else if (CODE.test(name) && !name.endsWith(".g.dart")) {
      out.push(full);
    }
  }
  return out;
}

export function readLintConfig(root: string): LintConfig {
  const path = join(root, "design/lint.json");
  return existsSync(path) ? (JSON.parse(readFileSync(path, "utf8")) as LintConfig) : {};
}

export function lintApp(root: string, config: LintConfig = readLintConfig(root)): Finding[] {
  const allow = new Set(config.allowPalettes ?? []);
  const active = MATCHERS.filter((m) => config.rules?.[m.rule] !== "off");
  const findings: Finding[] = [];
  for (const full of walk(root, root, config.ignore ?? [])) {
    const text = readFileSync(full, "utf8");
    if (/GENERATED by /.test(text.slice(0, 300))) continue;
    const file = relative(root, full);
    const seen = new Set<string>();
    text.split("\n").forEach((line, i) => {
      for (const m of active) {
        if (!m.applies(file)) continue;
        for (const match of m.find(line)) {
          if (m.rule === "stock-palette" && allow.has(match.match(/-(\w+)-\d+$/)?.[1] ?? "")) continue;
          const key = `${i}|${m.rule}`;
          if (seen.has(key)) continue;
          seen.add(key);
          findings.push({ file, line: i + 1, rule: m.rule, match });
        }
      }
    });
  }
  return findings.sort((a, b) => a.file.localeCompare(b.file) || a.line - b.line || a.rule.localeCompare(b.rule));
}

export type Baseline = { version: 1; findings: Record<string, number> };
const baselineKey = (f: Finding) => `${f.file}|${f.rule}|${f.match}`;

export function toBaseline(findings: Finding[]): Baseline {
  const counts: Record<string, number> = {};
  for (const f of findings) counts[baselineKey(f)] = (counts[baselineKey(f)] ?? 0) + 1;
  return { version: 1, findings: counts };
}

/** Findings not covered by the baseline (a baseline entry covers as many findings as its count). */
export function newFindings(findings: Finding[], baseline: Baseline): Finding[] {
  const left = { ...baseline.findings };
  return findings.filter((f) => {
    const k = baselineKey(f);
    if (left[k] > 0) {
      left[k]--;
      return false;
    }
    return true;
  });
}
